for t in targets:
    sum(x[i,t] for i in nodes if (i,t) in A) == sum(x[t,j] for j in nodes if (t,j) in A)
for s in fas:
    sum(x[s,j] for j in nodes if (s,j) in A) == sum(x[i,s] for i in nodes if (i,s) in A)

# Wrong
for t in T:
    sum(x[i,t] for i in V if (i,t) in A) == 1
    sum(x[t,j] for j in V if (t,j) in A) == 1
# no subtour elimination

# Correct
for i in T:
    for j in T:
        if i != j:
            u[i] - u[j] + |T| * x[i,j] <= |T| - 1

