# Wrong
for t in T:
    sum(x[i,t] for i in N if (i,t) in A) == 1
    sum(x[t,j] for j in N if (t,j) in A) == 1

# Correct
u = model.addVars(T, vtype=GRB.CONTINUOUS)
for i in T:
    for j in T:
        if i != j and (i,j) in A:
            model.addConstr(u[i] - u[j] + |T|*x[i,j] <= |T|-1)

